mapper.select:
SELECT external_identity.id AS identity_id, external_identity.provider_id, external_identity.account_id, external_identity.external_subject, external_identity.display_name AS external_display_name, external_identity.email, external_identity.email_verified, external_identity.avatar_uri, external_identity.last_authenticated_at, external_identity.version AS identity_version, provider.scope_type AS provider_scope_type, provider.scope_id AS provider_scope_id, provider.status AS provider_status, subject.id AS subject_id, subject.display_name AS subject_display_name, subject.status AS subject_status, subject.version AS subject_version, account.scope_type AS account_scope_type, account.scope_id AS account_scope_id, account.status AS account_status, account.second_factor_required, account.version AS account_version FROM iam_external_identity external_identity JOIN iam_identity_provider provider ON provider.id = external_identity.provider_id AND provider.deleted = 0 JOIN iam_account account ON account.id = external_identity.account_id AND account.deleted = 0 JOIN iam_subject subject ON subject.id = account.subject_id AND subject.deleted = 0 WHERE external_identity.deleted = 0
AND external_identity.id = #{identityId}
AND external_identity.provider_id = #{providerId} AND external_identity.external_subject = #{externalSubject}

mapper.update:
UPDATE iam_external_identity
SET deleted = 1,
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{identityId}
  AND account_id = #{accountId}
  AND version = #{version}
  AND deleted = 0
